@Component({
  selector: 'app-sidebar-offcanvas',
  imports: [
    CommonModule,
    MenuOptionComponent,
    VersionComponent
  ],
  templateUrl: './sidebar-offcanvas.component.html',
  styleUrl: './sidebar-offcanvas.component.css'
})
export class SidebarOffcanvasComponent {
  currentRoute: string = '';
  permisos: Permiso[] = []
  user: any
  menuExpanded: boolean = true
  @Input() menuOptions: MenuOption[] = MENU_OPTIONS

  logo_name = !!environment.logo_name ? environment.logo_name : 'main_logo.png'
  logo_url: String

  constructor(
    private router: Router,
    private store: LocalStorageService,
    public auth: AuthService,
    public version: VersionService,
  ) {
    if (this.store.isUserLogged()) {
      this.user = this.store.getUser()
    }

    this.permisos = (this.store.getPerfil().permisos_usuarios ?? []).filter(pu => pu.permisos !== undefined).map(pu => pu.permisos!)

    this.logo_url = '../../../assets/' + this.logo_name
  }

  ngOnInit() {
  }

  hasPermiso(key: string | undefined): boolean {
    if (!key) {
      return true
    }
    const tienePermiso = this.permisos.some(p => p.nombre.includes(key))

    return tienePermiso
  }

  isCollapsed() {
    const regex = /\/(clientes|usuarios|mercancias|almacenajes|servicios)\//;
    if (regex.test(this.router.url)) {
      return true
    }
    return false
  }

  sign_out() {
    this.store.deleteUser();
    this.router.navigate(['/']);
  }

  actual_route(): string {
    return this.router.url;
  }
}
