import { CommonModule } from '@angular/common';
import { Component, Input, SimpleChanges, input } from '@angular/core';
import { Router, RouterLink } from '@angular/router';
import { Permiso } from '../../../models/permiso.model';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

export interface MenuOption {
  label: String;
  tooltip?: string;
  icon?: String;
  icon_fill?: String;
  route_include?: String;
  router_link?: string;
  sub_menu?: MenuOption[];
  permiso?: string;
}

@Component({
  selector: 'app-menu-option',
  imports: [
    CommonModule,
    RouterLink
  ],
  templateUrl: './menu-option.component.html',
  styleUrl: './menu-option.component.css'
})
export class MenuOptionComponent {
  @Input() menu_option: MenuOption = {
    label: '',
    icon: '',
  }
  @Input() menuExpanded: boolean = true
  @Input() icon_size: String = ''
  @Input() label_size: String = ''
  subMenuExpandClass: string = 'd-none'
  @Input() showLabels: boolean = true
  @Input() classColor: string = 'bg-primary'
  permisos: Permiso[] = []



  constructor(
    private router: Router,
    private store: LocalStorageService,
  ) {
    this.permisos= (this.store.getPerfil().permisos_usuarios??[]).filter(pu => pu.permisos !== undefined).map( pu => pu.permisos! )
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['menuExpanded']) {
      if (this.menuExpanded) {
        setTimeout(() => {
          this.showLabels = this.menuExpanded
        }, 200)
      } else {
        this.showLabels = false
        this.subMenuExpandClass = 'd-none'
      }
    }
  }

  icon(): String | undefined {
    return this.isOptionInRoute() ? this.menu_option.icon_fill ?? this.menu_option.icon : this.menu_option.icon
  }

  isOptionInRoute() {
    return this.actual_route().includes((this.menu_option.route_include ?? '').toString())
  }

  actual_route(): string {
    return this.router.url;
  }

  hasPermiso(key: string | undefined): boolean {
    if (!key) {
      return true
    }
    const tienePermiso = this.permisos.some(p => p.nombre.includes(key))

    return tienePermiso
  }

  collapse() {
    if (this.subMenuExpandClass == 'd-none') {
      this.subMenuExpandClass = 'animate__fadeInLeft'
    } else {
      this.subMenuExpandClass = 'animate__fadeOutLeft'
      setTimeout(() => { this.subMenuExpandClass = 'd-none' }, 150)
    }
  }
}
